    return {}


def _compositions(item: str, answers: dict) -> list[tuple[str, int]]:
    """The complete memory answers that write an item as one part of themselves.

    Empty when the memory also writes the item as an answer of its own (then the item is
    already the whole wording), and empty when the memory writes it in more compositions
    than can be quoted (then none of them is the convention and listing some would make an
    arbitrary choice look canonical).
